data.minimal_example:
final mbtiles = MbTiles(path: mbTilesPath, gzip: true);

FlutterMap(
  options: MapOptions(
    minZoom: 8,
    maxZoom: 18,
    initialZoom: 11,
  ),
  children: [
    VectorTileLayer(
      theme: _theme,
      tileProviders: TileProviders({
        'openmaptiles': MbTilesVectorTileProvider(
          mbtiles: mbtiles,
        ),
      }),
      maximumZoom: 18,
    ),
  ],
)
